import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    # Check if any feature shows significant association with outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        x = feats.x[:, i]
        y = feats.y
        # Calculate effect size (mean difference)
        mean_y1 = np.mean(x[y == 1])
        mean_y0 = np.mean(x[y == 0])
        effect_size = mean_y1 - mean_y0

        # Welch's t-test
        group1 = x[y == 1]
        group0 = x[y == 0]
        if len(group1) > 1 and len(group0) > 1:
            t_stat, p_val = stats.ttest_ind(group1, group0, equal_var=False)
            if p_val < 0.05 and abs(effect_size) > 0.1:
                effects.append((abs(effect_size), fid, p_val, t_stat))

    # Sort by effect size
    effects.sort(reverse=True)

    # Check for near-duplicates using correlation
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Remove near-duplicates, keeping the one with stronger effect
    selected_ids = set()
    for effect_size, fid, p_val, t_stat in effects:
        skip = False
        for dup_fid in selected_ids:
            if (fid, dup_fid) in correlations or (dup_fid, fid) in correlations:
                skip = True
                break
        if not skip:
            selected_ids.add(fid)

    # Limit to MAX_DRIVERS
    top_features = list(selected_ids)[:MAX_DRIVERS]

    # If no strong associations, return empty design
    if len(top_features) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Simple approach: Use top features directly
    return Design(
        drivers=tuple(top_features),
        columns=tuple(top_features),
        products=(),
        loadings={fid: 1.0 for fid in top_features}
    )

